    79→        private static readonly Dictionary<RlpDecoderKey, IRlpDecoder> _decoderBuilder = new();
    80→        private static FrozenDictionary<RlpDecoderKey, IRlpDecoder>? _decoders;
    81→        private static Lock _decoderLock = new();
    82→        public static FrozenDictionary<RlpDecoderKey, IRlpDecoder> Decoders
    83→        {
    84→            get
    85→            {
    86→                FrozenDictionary<RlpDecoderKey, IRlpDecoder> decoders = _decoders;
