   124→            {
   125→                if (!type.IsClass || type.IsAbstract || type.IsGenericTypeDefinition)
   126→                {
   127→                    continue;
   128→                }
   129→
   130→                if (type.GetCustomAttribute<SkipGlobalRegistration>() is not null)
   131→                {
   132→                    continue;
   133→                }
   134→
   135→                Type[]? implementedInterfaces = type.GetInterfaces();
   136→                foreach (Type? implementedInterface in implementedInterfaces)
   137→                {
   138→                    if (!implementedInterface.IsGenericType)
   139→                    {
   140→                        continue;
   141→                    }
